import { z } from "zod";
const zStatsProps = z.object({
    label: z.string().optional(),
    value: z.string().optional(),
    helpText: z.string().optional(),
    indicator: z.enum(["increase", "decrease", "unchanged"]).optional(),
});
export function StatsWidget(define) {
    return define("Stats")
        .props(zStatsProps)
        .render((props) => props);
}
